// ---- TrueNAS Garry's Mod VM rotation config ----
// There are six VM IDs in the uploaded workflow: 50, 51, 52, 54, 55, and 56.
// Each run:
//   1. Check and stop all six VMs if they are RUNNING.
//   2. Pick exactly 4 of the 6 VMs at random.
//   3. Give each selected VM its own random, unique start offset from 0-15 minutes.
//      Example: one starts at 3m, another at 4m, another at 11m, another at 15m.
// Stop/status/start HTTP nodes are configured to continue on errors, because TrueNAS can reject
// vm.stop or vm.start if a VM changes state between checks and commands.
// Start branches re-check status immediately before starting to avoid "already running" 422 errors.

const TRUE_NAS_BASE_URL = 'https://10.128.0.6';
const VMS = [
  { id: 50, name: 'GMod VM 50' },
  { id: 51, name: 'GMod VM 51' },
  { id: 52, name: 'GMod VM 52' },
  { id: 54, name: 'GMod VM 54' },
  { id: 55, name: 'GMod VM 55' },
  { id: 56, name: 'GMod VM 56' },
];

const START_COUNT = 4;
const START_WINDOW_MINUTES = 15;

if (START_COUNT > VMS.length) {
  throw new Error(`START_COUNT (${START_COUNT}) cannot be greater than VM count (${VMS.length}).`);
}
if (START_COUNT > START_WINDOW_MINUTES + 1) {
  throw new Error('START_COUNT requires more unique minute slots than the configured window allows.');
}

function shuffle(array) {
  const copy = [...array];
  for (let i = copy.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [copy[i], copy[j]] = [copy[j], copy[i]];
  }
  return copy;
}

const selected = shuffle(VMS).slice(0, START_COUNT);
const selectedIds = new Set(selected.map(vm => vm.id));
const excluded = VMS.filter(vm => !selectedIds.has(vm.id));

// Pick unique minute offsets so the 4 selected VMs are staggered instead of accidentally all starting together.
const delayMinuteSlots = shuffle(Array.from({ length: START_WINDOW_MINUTES + 1 }, (_, i) => i)).slice(0, START_COUNT);

const startSchedule = selected
  .map((vm, index) => ({
    ...vm,
    delayMinutes: delayMinuteSlots[index],
    delaySeconds: delayMinuteSlots[index] * 60,
  }))
  .sort((a, b) => a.delayMinutes - b.delayMinutes);

return [
  {
    json: {
      runId: new Date().toISOString(),
      baseUrl: TRUE_NAS_BASE_URL,
      vmIds: VMS.map(vm => vm.id),
      vmPool: VMS,
      startCount: START_COUNT,
      startWindowMinutes: START_WINDOW_MINUTES,
      selectedVmIds: startSchedule.map(vm => vm.id),
      excludedVmIds: excluded.map(vm => vm.id),
      startSchedule,
      note: 'Each startSchedule entry has its own delayMinutes value. A delay of 0 means start immediately after the stop/status phase.',
    },
  },
];
